using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json.Nodes;
using Jindan.Contracts;
using Jindan.Core;
using Jindan.Infrastructure;
static class Program{
 static readonly string Root=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../artifacts/domain-tests",Guid.NewGuid().ToString("N")));
 static int Passed,Failed;
 static void Check(bool condition,string message="Assertion failed"){if(!condition)throw new Exception(message);}
 static async Task Throws(Func<Task> action,params string[] codes){try{await action();}catch(WorkspaceException e){Check(codes.Contains(e.Code),"Unexpected code: "+e.Code);return;}throw new Exception("Expected WorkspaceException: "+string.Join(',',codes));}
 static void ThrowsSync(Action action,string code){try{action();}catch(WorkspaceException e){Check(e.Code==code);return;}throw new Exception("Expected "+code);}
 static LocalWorkspace Workspace(string name){var w=new LocalWorkspace(Path.Combine(Root,name));Schemas(w);return w;}
 static void Schemas(LocalWorkspace w){w.RegisterSchema(new RecordSchema("projects","Projects",[new("name","Name",Required:true),new("startDate","Start","date"),new("endDate","End","date")],false));w.RegisterSchema(new RecordSchema("processes","Processes",[new("name","Name",Required:true),new("startDate","Start","date"),new("endDate","End","date")],true));w.RegisterSchema(new RecordSchema("photos","Photos",[new("name","Name",Required:true),new("assetId","Asset")],true));w.RegisterSchema(new RecordSchema("tasks","Tasks",[new("name","Name",Required:true),new("relatedProjectId","Project"),new("isPublic","Public",Choices:["false","true"])],false));w.RegisterSchema(new RecordSchema("board","Board",[new("name","Name",Required:true)],false));}
 static RecordDraft Draft(string kind,string name,string? project=null)=>new(null,kind,project,0,new(){{"name",name}});
 static Task<Identity> Admin(LocalWorkspace w)=>w.BootstrapAsync("Local owner","unique-password-66",true);
 static async Task Test(string name,Func<Task> action){try{await action();Passed++;Console.WriteLine("PASS "+name);}catch(Exception e){Failed++;Console.WriteLine("FAIL "+name+" "+e.GetType().Name+": "+e.Message);}}
 public static async Task<int> Main(){Directory.CreateDirectory(Root);
 await Test("bootstrap explicit local consent, password policy, no hardcoded identity",async()=>{using var w=Workspace("identity");Check(!w.IsInitialized);await Throws(()=>w.BootstrapAsync("Owner","unique-password-66",false),"CONFIRMATION");await Throws(()=>w.BootstrapAsync("Owner","tiny",true),"PASSWORD_POLICY");var a=await Admin(w);Check(w.IsInitialized&&a.Role=="admin");await Throws(()=>w.BootstrapAsync("Other","unique-password-66",true),"INITIALIZED");await Throws(()=>w.LoginAsync("admin","admin"),"AUTH_FAILED");var json=File.ReadAllText(Path.Combine(w.DataRoot,"workspace.json"));Check(!json.Contains("unique-password-66")&&json.Contains("PasswordHash")&&json.Contains("Salt"));});
 await Test("forged actor, role mutation and cross-instance identity are rejected",async()=>{using var w=Workspace("forgery");var a=await Admin(w);await Throws(()=>w.ListAsync(a with{},new RecordQuery("projects")),"UNAUTHENTICATED");await Throws(()=>w.ListAsync(new Identity(a.Id,a.DisplayName,"admin",[]),new RecordQuery("projects")),"UNAUTHENTICATED");using var other=new LocalWorkspace(w.DataRoot);Schemas(other);await Throws(()=>other.ListAsync(a,new RecordQuery("projects")),"UNAUTHENTICATED");});
 await Test("project child isolation and canonical persisted membership",async()=>{using var w=Workspace("scope");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","P1"));var q=await w.SaveAsync(a,Draft("projects","P2"));var u=await w.SaveUserAsync(a,null,"Editor","editor",[p.Id],false,"editor-password-66");var e=await w.LoginAsync("Editor","editor-password-66");var r=await w.SaveAsync(e,Draft("processes","Own process",p.Id));Check((await w.ListAsync(e,new RecordQuery("projects"))).Count==1);await Throws(()=>w.ListAsync(e,new RecordQuery("processes",q.Id)),"FORBIDDEN");await Throws(()=>w.SaveAsync(e,Draft("processes","Wrong project",q.Id)),"FORBIDDEN");await Throws(()=>w.SaveAsync(e,new(r.Id,"processes",q.Id,r.Revision,r.Fields)),"PROJECT_SCOPE");await w.SaveUserAsync(a,u.Id,"Editor","editor",[],false,null);await Throws(()=>w.SaveAsync(e,new(r.Id,"processes",p.Id,r.Revision,r.Fields)),"FORBIDDEN");Check((await w.ListAsync(e,new RecordQuery("processes"))).Count==0);});
 await Test("viewer cannot write; owner tasks and shared board author boundary",async()=>{using var w=Workspace("roles");var a=await Admin(w);await w.SaveUserAsync(a,null,"E1","editor",[],false,"editor-password-66");await w.SaveUserAsync(a,null,"E2","editor",[],false,"editor-password-66");await w.SaveUserAsync(a,null,"Viewer","viewer",[],false,"viewer-password-66");var e1=await w.LoginAsync("E1","editor-password-66");var e2=await w.LoginAsync("E2","editor-password-66");var v=await w.LoginAsync("Viewer","viewer-password-66");await w.SaveAsync(e1,Draft("tasks","Personal"));Check((await w.ListAsync(e2,new RecordQuery("tasks"))).Count==0);var b=await w.SaveAsync(e1,Draft("board","Shared"));Check((await w.ListAsync(e2,new RecordQuery("board"))).Count==1);await Throws(()=>w.SaveAsync(e2,new(b.Id,"board",null,b.Revision,b.Fields)),"FORBIDDEN");await Throws(()=>w.SaveAsync(v,Draft("board","Denied")),"FORBIDDEN");await Throws(()=>w.ListAsync(e1),"FORBIDDEN");});
 await Test("schema, required fields, date ordering, revision and input immutability",async()=>{using var w=Workspace("validation");var a=await Admin(w);await Throws(()=>w.SaveAsync(a,Draft("unknown","x")),"SCHEMA_REQUIRED");await Throws(()=>w.SaveAsync(a,new(null,"projects",null,0,new())),"VALIDATION");await Throws(()=>w.SaveAsync(a,new(null,"projects",null,0,new(){{"name","x"},{"startDate","2026-02-30"}})),"DATE");await Throws(()=>w.SaveAsync(a,new(null,"projects",null,0,new(){{"name","x"},{"startDate","2026-12-01"},{"endDate","2026-01-01"}})),"DATE");var d=Draft("projects","Immutable");var r=await w.SaveAsync(a,d);d.Fields["name"]="mutated";r.Fields["name"]="mutated output";Check((await w.ListAsync(a,new RecordQuery("projects")))[0].Fields["name"]=="Immutable");await Throws(()=>w.SaveAsync(a,new(r.Id,"projects",null,0,new(){{"name","stale"}})),"REVISION");});
 await Test("multi-instance revision lease prevents stale overwrite",async()=>{using var w=Workspace("concurrency");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","First"));using var other=new LocalWorkspace(w.DataRoot);Schemas(other);var b=await other.LoginAsync("Local owner","unique-password-66");var updated=await w.SaveAsync(a,new(p.Id,"projects",null,p.Revision,new(){{"name","Updated"}}));await Throws(()=>other.SaveAsync(b,new(p.Id,"projects",null,p.Revision,new(){{"name","Stale"}})),"REVISION");Check((await other.ListAsync(b,new RecordQuery("projects")))[0].Revision==updated.Revision);});
 await Test("logical deletion requires explicit confirmation",async()=>{using var w=Workspace("delete");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","Kept"));await Throws(()=>w.DeleteAsync(a,"projects",p.Id,p.Revision,false),"CONFIRMATION");Check((await w.ListAsync(a,new RecordQuery("projects"))).Count==1);await w.DeleteAsync(a,"projects",p.Id,p.Revision,true);Check((await w.ListAsync(a,new RecordQuery("projects"))).Count==0);Check((await w.ListAsync(a,new RecordQuery("projects",IncludeDeleted:true)))[0].Deleted);});
 await Test("restart persistence, cloned layout and password/admin edit",async()=>{string path;using(var w=Workspace("restart")){path=w.DataRoot;var a=await Admin(w);await w.SaveAsync(a,Draft("projects","Persisted"));var bounds=new Dictionary<string,int[]>{{"left",[10,20,300,400]}};await w.SaveAsync(new AppLayout(310,330,FloatingBounds:bounds));bounds["left"][2]=900;await w.ChangePasswordAsync(a,"unique-password-66","changed-password-66");await Throws(()=>w.LoginAsync("Local owner","unique-password-66"),"AUTH_FAILED");await Throws(()=>w.SaveUserAsync(a,a.Id,a.DisplayName,"viewer",[],false,null),"LAST_ADMIN");}using var reopened=new LocalWorkspace(path);Schemas(reopened);var b=await reopened.LoginAsync("Local owner","changed-password-66");Check((await reopened.ListAsync(b,new RecordQuery("projects"))).Single().Fields["name"]=="Persisted");var layout=await reopened.LoadAsync();Check(layout.LeftWidth==310&&layout.FloatingBounds!["left"][2]==300);});
 await Test("content assets preserve source, deduplicate, authorize and export a new copy",async()=>{using var w=Workspace("assets");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","P"));var q=await w.SaveAsync(a,Draft("projects","Q"));var source=Path.Combine(Root,"original.dat");File.WriteAllBytes(source,[1,2,3,4,5]);var hash=Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(source)));var x=await w.ImportAsync(a,p.Id,source);var same=await w.ImportAsync(a,p.Id,source);Check(x.Id==same.Id&&x.Sha256==hash&&File.ReadAllBytes(source).SequenceEqual(new byte[]{1,2,3,4,5}));await w.SaveUserAsync(a,null,"Other","editor",[q.Id],false,"other-password-66");var other=await w.LoginAsync("Other","other-password-66");await Throws(()=>w.GetAsync(other,x.Id),"FORBIDDEN");var destination=Path.Combine(Root,"export-original.dat");await w.ExportAsync(a,x.Id,destination);Check(File.ReadAllBytes(destination).SequenceEqual(File.ReadAllBytes(source)));await Throws(()=>w.ExportAsync(a,x.Id,destination),"DESTINATION");using(var locked=new FileStream(source,FileMode.Open,FileAccess.ReadWrite,FileShare.None))await Throws(()=>w.ImportAsync(a,q.Id,source),"ASSET_IO");var cancel=new CancellationToken(true);try{await w.ImportAsync(a,p.Id,source,cancel);throw new Exception("Expected cancellation");}catch(OperationCanceledException){}File.WriteAllBytes(x.StoredPath,[9,9]);await Throws(()=>w.GetAsync(a,x.Id),"CORRUPT_ASSET");});
 await Test("export preview new-copy import preserves originals and remaps asset/project IDs; rollback",async()=>{using var w=Workspace("transfer");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","Original"));var source=Path.Combine(Root,"transfer-asset.dat");File.WriteAllBytes(source,[7,8,9]);var asset=await w.ImportAsync(a,p.Id,source);await w.SaveAsync(a,new(null,"photos",p.Id,0,new(){{"name","Photo"},{"assetId",asset.Id}}));var package=Path.Combine(Root,"transfer.zip");await w.ExportAsync(a,package);var preview=await w.PreviewImportAsync(a,package);Check(preview.Records==2&&preview.Warnings.Count>0);await Throws(()=>w.ImportAsync(a,preview,false),"CONFIRMATION");await w.ImportAsync(a,preview,true);var projects=await w.ListAsync(a,new RecordQuery("projects"));Check(projects.Count==2&&projects.Any(x=>x.Id==p.Id));var copy=projects.Single(x=>x.Id!=p.Id);var photo=(await w.ListAsync(a,new RecordQuery("photos",copy.Id))).Single();Check(photo.Fields["assetId"]!=asset.Id);Check((await w.GetAsync(a,photo.Fields["assetId"])).Sha256==asset.Sha256);await w.RollbackLastImportAsync(a,true);Check((await w.ListAsync(a,new RecordQuery("projects"))).Count==1);});
 await Test("stale preview, malformed and duplicate ZIP inputs fail closed",async()=>{using var w=Workspace("bad-import");var a=await Admin(w);await w.SaveAsync(a,Draft("projects","Data"));var path=Path.Combine(Root,"stale.zip");await w.ExportAsync(a,path);var preview=await w.PreviewImportAsync(a,path);using(var zip=ZipFile.Open(path,ZipArchiveMode.Update)){var entry=zip.GetEntry("data.json")!;string json;using(var r=new StreamReader(entry.Open()))json=r.ReadToEnd();entry.Delete();using var output=new StreamWriter(zip.CreateEntry("data.json").Open());output.Write(json.Replace("Data","Changed",StringComparison.Ordinal));}await Throws(()=>w.ImportAsync(a,preview,true),"STALE_PREVIEW");var duplicate=Path.Combine(Root,"duplicate.zip");using(var zip=ZipFile.Open(duplicate,ZipArchiveMode.Create)){zip.CreateEntry("data.json");zip.CreateEntry("data.json");}await Throws(()=>w.PreviewImportAsync(a,duplicate),"DUPLICATE_ZIP");var malformed=Path.Combine(Root,"malformed.zip");File.WriteAllText(malformed,"notzip");await Throws(()=>w.PreviewImportAsync(a,malformed),"CORRUPT_IMPORT");});
 await Test("rollback refuses to overwrite subsequent work",async()=>{using var w=Workspace("rollback-revision");var a=await Admin(w);await w.SaveAsync(a,Draft("projects","Original"));var path=Path.Combine(Root,"rollback.zip");await w.ExportAsync(a,path);var preview=await w.PreviewImportAsync(a,path);await w.ImportAsync(a,preview,true);await w.SaveAsync(a,Draft("projects","Newer"));await Throws(()=>w.RollbackLastImportAsync(a,true),"REVISION");Check((await w.ListAsync(a,new RecordQuery("projects"))).Count==3);});
 await Test("corrupt primary recovers backup and preserves corrupt evidence; future schema blocked",async()=>{string path;using(var w=Workspace("recovery")){path=w.DataRoot;var a=await Admin(w);await w.SaveAsync(a,Draft("projects","Backup state"));await w.SaveAsync(a,Draft("projects","Latest"));}File.WriteAllText(Path.Combine(path,"workspace.json"),"{broken");using(var restored=new LocalWorkspace(path)){Schemas(restored);Check(restored.RecoveredFromBackup);var a=await restored.LoginAsync("Local owner","unique-password-66");Check((await restored.ListAsync(a,new RecordQuery("projects"))).Count==1);Check(Directory.GetFiles(path,"workspace.corrupt-*.json").Length==1);}var data=JsonNode.Parse(File.ReadAllText(Path.Combine(path,"workspace.json")))!;data["SchemaVersion"]=99;File.WriteAllText(Path.Combine(path,"workspace.json"),data.ToJsonString());ThrowsSync(()=>new LocalWorkspace(path),"SCHEMA_FUTURE");});
 await Test("atomic locked-save failure preserves persisted data and revision",async()=>{using var w=Workspace("atomic");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","Before"));var path=Path.Combine(w.DataRoot,"workspace.json");var before=File.ReadAllBytes(path);using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){try{await w.SaveAsync(a,new(p.Id,"projects",null,p.Revision,new(){{"name","Fail"}}));throw new Exception("Expected locked replace failure");}catch(IOException){}}Check(File.ReadAllBytes(path).SequenceEqual(before));Check((await w.ListAsync(a,new RecordQuery("projects")))[0].Revision==p.Revision);Check(Directory.GetFiles(w.DataRoot,"*.tmp-*").Length==0);});
 await Test("legacy and maintenance roots immutable by path policy",()=>{ThrowsSync(()=>new LocalWorkspace("F:/jindan/output/forbidden-domain-test"),"PROTECTED_ROOT");ThrowsSync(()=>new LocalWorkspace("F:/jindan-maintenance/forbidden-domain-test"),"PROTECTED_ROOT");return Task.CompletedTask;});

 await Test("disabled sessions, admin user edit, schema conflict and linked asset project guard",async()=>{using var w=Workspace("more-guards");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","P"));var q=await w.SaveAsync(a,Draft("projects","Q"));var u=await w.SaveUserAsync(a,null,"Member","editor",[p.Id],false,"member-password-66");var e=await w.LoginAsync("Member","member-password-66");await w.SaveUserAsync(a,u.Id,"Member","editor",[p.Id],true,null);await Throws(()=>w.ListAsync(e,new RecordQuery("projects")),"UNAUTHENTICATED");await Throws(()=>w.LoginAsync("Member","member-password-66"),"AUTH_FAILED");ThrowsSync(()=>w.RegisterSchema(new("projects","Different",[],false)),"SCHEMA_CONFLICT");var file=Path.Combine(Root,"guard-asset.dat");File.WriteAllBytes(file,[1]);var asset=await w.ImportAsync(a,p.Id,file);await Throws(()=>w.SaveAsync(a,new(null,"photos",q.Id,0,new(){{"name","Wrong asset"},{"assetId",asset.Id}})),"PROJECT_SCOPE");});
 await Test("cancelled save leaves bytes unchanged and locked workspace lease honors cancellation",async()=>{using var w=Workspace("cancel-state");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","Before"));var path=Path.Combine(w.DataRoot,"workspace.json");var before=File.ReadAllBytes(path);try{await w.SaveAsync(a,new(p.Id,"projects",null,p.Revision,new(){{"name","Cancelled"}}),new CancellationToken(true));throw new Exception("Expected cancel");}catch(OperationCanceledException){}Check(File.ReadAllBytes(path).SequenceEqual(before));using var lease=new FileStream(Path.Combine(w.DataRoot,"workspace.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None);using var cts=new CancellationTokenSource(100);try{await w.ListAsync(a,new RecordQuery("projects"),cts.Token);throw new Exception("Expected cancellation during lease wait");}catch(OperationCanceledException){}Check(File.ReadAllBytes(path).SequenceEqual(before));});

 await Test("public tasks readable locally but only author/admin writable; active admin cannot self-disable",async()=>{using var w=Workspace("public-tasks");var a=await Admin(w);await w.SaveUserAsync(a,null,"WriterA","editor",[],false,"writer-password-66");await w.SaveUserAsync(a,null,"WriterB","editor",[],false,"writer-password-66");var e=await w.LoginAsync("WriterA","writer-password-66");var b=await w.LoginAsync("WriterB","writer-password-66");await w.SaveAsync(e,Draft("tasks","Private"));var pub=await w.SaveAsync(e,new(null,"tasks",null,0,new(){{"name","Public"},{"isPublic","true"}}));var read=await w.ListAsync(b,new RecordQuery("tasks"));Check(read.Count==1&&read[0].Id==pub.Id);await Throws(()=>w.SaveAsync(b,new(pub.Id,"tasks",null,pub.Revision,pub.Fields)),"FORBIDDEN");await Throws(()=>w.DeleteAsync(b,"tasks",pub.Id,pub.Revision,true),"FORBIDDEN");await w.SaveUserAsync(a,null,"SecondAdmin","admin",[],false,"second-admin-password");await Throws(()=>w.SaveUserAsync(a,a.Id,a.DisplayName,"admin",[],true,null),"SELF_DISABLE");});
 await Test("report document authorization rechecks authenticated actor, current role, membership and deletion",async()=>{using var w=Workspace("document-auth");var a=await Admin(w);var p=await w.SaveAsync(a,Draft("projects","P"));var q=await w.SaveAsync(a,Draft("projects","Q"));var user=await w.SaveUserAsync(a,null,"ReportEditor","editor",[p.Id],false,"editor-password-66");var e=await w.LoginAsync("ReportEditor","editor-password-66");var context=new DocumentContext("document-auth","report-studio",p.Id,e.Id);await w.AuthorizeDocumentAsync(e,context,true);await Throws(()=>w.AuthorizeDocumentAsync(e,context with{UserId=a.Id},false),"UNAUTHENTICATED");await Throws(()=>w.AuthorizeDocumentAsync(e with{},context,false),"UNAUTHENTICATED");await Throws(()=>w.AuthorizeDocumentAsync(e,context with{ProjectId=q.Id},false),"FORBIDDEN");await w.SaveUserAsync(a,user.Id,"ReportEditor","viewer",[p.Id],false,null);await w.AuthorizeDocumentAsync(e,context,false);await Throws(()=>w.AuthorizeDocumentAsync(e,context,true),"FORBIDDEN");await w.SaveUserAsync(a,user.Id,"ReportEditor","editor",[],false,null);await Throws(()=>w.AuthorizeDocumentAsync(e,context,false),"FORBIDDEN");await w.DeleteAsync(a,"projects",p.Id,p.Revision,true);await Throws(()=>w.AuthorizeDocumentAsync(a,context with{UserId=a.Id},false),"FORBIDDEN");});
 await Test("native schedule matches preserved JS golden vectors without conflating completion ratio",()=>{var repo=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../"));var golden=JsonNode.Parse(File.ReadAllText(Path.Combine(repo,"tests/fixtures/schedule66/golden.json")))!;foreach(var item in golden["vectors"]!.AsArray()){var fields=item!["fields"]!.AsObject().ToDictionary(p=>p.Key,p=>p.Value!.GetValue<string>());var actual=Schedule.Get(fields,DateOnly.Parse(item["today"]!.GetValue<string>()));var expected=item["expected"]!;Check(actual.Progress==expected["progress"]!.GetValue<int>()&&actual.Status==expected["status"]!.GetValue<string>()&&actual.DaysRemaining==expected["daysRemaining"]?.GetValue<int>()&&actual.IsValid==expected["isValid"]!.GetValue<bool>(),"Schedule golden mismatch: "+item["id"]);}return Task.CompletedTask;});
 await Test("local member position persists without becoming role authority",async()=>{using var w=Workspace("profile-position");var a=await Admin(w);var u=await w.SaveUserProfileAsync(a,null,"Field engineer","기술진단 담당","editor",[],false,"engineer-test-password");Check(u.Position=="기술진단 담당");await w.SaveUserAsync(a,u.Id,"Field engineer","viewer",[],false,null);Check((await w.ListAsync(a)).Single(x=>x.Id==u.Id).Position==u.Position);var e=await w.LoginAsync("Field engineer","engineer-test-password");await Throws(()=>w.SaveUserProfileAsync(e,u.Id,"Field engineer","관리자","admin",[],false,null),"FORBIDDEN");await Throws(()=>w.SaveUserProfileAsync(a,u.Id,"Field engineer",new string('x',101),"admin",[],false,null),"VALIDATION");var saved=(await w.ListAsync(a)).Single(x=>x.Id==u.Id);Check(saved.Role=="viewer"&&saved.Position==u.Position);});
 await Test("existing project catalog remains readable when its feature DLL schema is absent",async()=>{string path;string project;using(var initial=Workspace("missing-project-module")){path=initial.DataRoot;var a=await Admin(initial);project=(await initial.SaveAsync(a,Draft("projects","Retained catalog"))).Id;}using var reopened=new LocalWorkspace(path);reopened.RegisterSchema(new("processes","Processes",[new("name","Name",Required:true)],true));var actor=await reopened.LoginAsync("Local owner","unique-password-66");Check((await reopened.ListAsync(actor,new RecordQuery("projects"))).Single().Id==project);await reopened.SaveAsync(actor,new(null,"processes",project,0,new(){{"name","Independent child module"}}));await Throws(()=>reopened.SaveAsync(actor,Draft("projects","Unavailable editor")),"SCHEMA_REQUIRED");Check((await reopened.ListAsync(actor,new RecordQuery("uninstalled-kind"))).Count==0);});
 Console.WriteLine($"RESULT pass={Passed} fail={Failed} syntheticRoot={Root}");return Failed==0?0:1;
